insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_criteria','criteria','noun','standards used to judge, choose, or decide something','[{"senseId":"criteria_1","meaning":"standards used to judge, choose, or decide something","acceptedParaphrases":["standards","rules for judging"],"masteryContexts":[{"contextId":"u1_41_criteria_meaning","text":"Speed and accuracy are two of the criteria used to select the team.","meaning":"standards used to make a judgement"},{"contextId":"u1_41_criteria_paraphrase","text":"The judges use several criteria when deciding the winner.","meaning":"conditions used for evaluating choices"}],"contextDependentParaphrases":[],"misleadingDistractors":["results","opinions","rewards"],"teacherNote":"Plural of criterion; use standards used for judging as the core meaning."}]'::jsonb,'[]'::jsonb,'["selection criteria","meet the criteria"]'::jsonb,'live'),
('vocab_historic','historic','adjective','important in history or likely to be remembered for a long time','[{"senseId":"historic_1","meaning":"important in history or likely to be remembered for a long time","acceptedParaphrases":["historically important","momentous"],"masteryContexts":[{"contextId":"u1_42_historic_meaning","text":"The victory was a historic moment for the small club.","meaning":"important enough to matter in history"},{"contextId":"u1_42_historic_paraphrase","text":"The team’s first international victory was historic.","meaning":"likely to be remembered historically"}],"contextDependentParaphrases":[],"misleadingDistractors":["old-fashioned","ordinary","recent"],"teacherNote":"Means important in history, not simply old or related to history."}]'::jsonb,'[]'::jsonb,'["historic victory","historic moment"]'::jsonb,'live'),
('vocab_selection','selection','noun','a range of things available to choose from or the act of choosing','[{"senseId":"selection_1","meaning":"a range of things available to choose from or the act of choosing","acceptedParaphrases":["choice","range"],"masteryContexts":[{"contextId":"u1_43_selection_meaning","text":"The shop has a wide selection of equipment for different sports.","meaning":"range of available choices"},{"contextId":"u1_43_selection_paraphrase","text":"The centre offers a wide selection of after-school activities.","meaning":"set from which items are chosen"}],"contextDependentParaphrases":[],"misleadingDistractors":["refusal","demand","result"]}]'::jsonb,'["select","selective"]'::jsonb,'["wide selection","selection process"]'::jsonb,'live'),
('vocab_produce','produce','verb','to make, create, or cause something to exist','[{"senseId":"produce_1","meaning":"to make, create, or cause something to exist","acceptedParaphrases":["make","create"],"masteryContexts":[{"contextId":"u1_44_produce_meaning","text":"Local craftspeople produce equipment by hand for traditional sports.","meaning":"bring something into existence"},{"contextId":"u1_44_produce_paraphrase","text":"The workshop produces specialist equipment for local teams.","meaning":"create or manufacture something"}],"contextDependentParaphrases":[],"misleadingDistractors":["destroy","borrow","select"],"grammarForms":{"base":"produce","thirdPerson":"produces","past":"produced","pastParticiple":"produced","ing":"producing"},"grammarPatterns":["produce + noun","be produced + passive"],"teacherNote":"Use the verb sense make/create in this unit."}]'::jsonb,'["production","producer"]'::jsonb,'[]'::jsonb,'live'),
('vocab_craftspeople','craftspeople','noun','people skilled at making things by hand','[{"senseId":"craftspeople_1","meaning":"people skilled at making things by hand","acceptedParaphrases":["skilled makers","artisans"],"masteryContexts":[{"contextId":"u1_45_craftspeople_meaning","text":"Local craftspeople make the wooden equipment using traditional methods.","meaning":"skilled workers who make things by hand"},{"contextId":"u1_45_craftspeople_paraphrase","text":"Skilled makers demonstrated how the traditional equipment was made.","meaning":"people with specialist hand-making skills"}],"contextDependentParaphrases":[],"misleadingDistractors":["spectators","athletes","customers"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_significant','significant','adjective','important or large enough to be noticed or have an effect','[{"senseId":"significant_1","meaning":"important or large enough to be noticed or have an effect","acceptedParaphrases":["important","notable"],"masteryContexts":[{"contextId":"u1_46_significant_meaning","text":"The new training programme led to a significant improvement in results.","meaning":"important enough to have an effect"},{"contextId":"u1_46_significant_paraphrase","text":"Regular exercise can have an significant effect on mental wellbeing.","meaning":"meaningful enough to make a difference"}],"contextDependentParaphrases":[],"misleadingDistractors":["famous","ordinary","tiny"],"teacherNote":"Do not accept big automatically. The unit sense is important/notable or large enough to have an effect."}]'::jsonb,'["significance","significantly"]'::jsonb,'["significant increase","significant difference","significant impact"]'::jsonb,'live'),
('vocab_expansion','expansion','noun','an increase in size, range, or amount','[{"senseId":"expansion_1","meaning":"an increase in size, range, or amount","acceptedParaphrases":["growth","increase"],"masteryContexts":[{"contextId":"u1_47_expansion_meaning","text":"The club’s expansion created space for several new sports.","meaning":"process of becoming larger in scope"},{"contextId":"u1_47_expansion_paraphrase","text":"The expansion of the league has attracted more young players.","meaning":"growth in size, range or amount"}],"contextDependentParaphrases":[],"misleadingDistractors":["reduction","delay","selection"]}]'::jsonb,'["expand","expansive"]'::jsonb,'["rapid expansion","business expansion"]'::jsonb,'live'),
('vocab_reputation','reputation','noun','the general opinion people have about someone or something','[{"senseId":"reputation_1","meaning":"the general opinion people have about someone or something","acceptedParaphrases":["public image","general opinion"],"masteryContexts":[{"contextId":"u1_48_reputation_meaning","text":"The academy has a strong reputation for developing young athletes.","meaning":"shared opinion others have formed"},{"contextId":"u1_48_reputation_paraphrase","text":"The reputation of the club improved after the campaign.","meaning":"public judgement built over time"}],"contextDependentParaphrases":[],"misleadingDistractors":["salary","achievement","permission"]}]'::jsonb,'["reputable","disreputable"]'::jsonb,'["good reputation","build a reputation"]'::jsonb,'live'),
('vocab_reasonable','reasonable','adjective','fair, sensible, or not too expensive or extreme','[{"senseId":"reasonable_1","meaning":"fair, sensible, or not too expensive or extreme","acceptedParaphrases":["fair","sensible"],"masteryContexts":[{"contextId":"u1_49_reasonable_meaning","text":"The entry fee is reasonable for a full day of activities.","meaning":"fair or sensible, not excessive"},{"contextId":"u1_49_reasonable_paraphrase","text":"Most students thought the membership fee was reasonable.","meaning":"within an acceptable moderate limit"}],"contextDependentParaphrases":[],"misleadingDistractors":["excessive","impossible","historic"],"teacherNote":"Use the fair/sensible/not excessive sense in this unit."}]'::jsonb,'["reasonably","unreasonable"]'::jsonb,'["reasonable price","reasonable explanation"]'::jsonb,'live'),
('vocab_antiques','antiques','noun','old objects that are valuable or interesting because of their age','[{"senseId":"antiques_1","meaning":"old objects that are valuable or interesting because of their age","acceptedParaphrases":["valuable old objects","collectable old items"],"masteryContexts":[{"contextId":"u1_50_antiques_meaning","text":"The market sells antiques alongside handmade sports memorabilia.","meaning":"valuable old objects kept for interest"},{"contextId":"u1_50_antiques_paraphrase","text":"Collectors travelled to the fair to buy antiques.","meaning":"collectable objects from an earlier period"}],"contextDependentParaphrases":[],"misleadingDistractors":["new equipment","souvenirs","documents"]}]'::jsonb,'[]'::jsonb,'["antique market","valuable antiques"]'::jsonb,'live')
